python3 -c "
import json

crm_detail = {
    'connectionId': 'd61e5d0e-04af-4f93-95cc-151d81fa08dc',
    'folderKey': 'c4359cde-55f0-4f0e-9322-c6cdce74ab4c',
    'method': 'POST',
    'endpoint': '/v2/{entityName}/qer',
    'pathParameters': {
        'entityName': 'BillingDisputeCRM'
    },
    'queryParameters': {
        'queryExpression': \"=js:\`accountNumber = '\${(\$vars.start.output.webhookPayload && \$vars.start.output.webhookPayload.customer && \$vars.start.output.webhookPayload.customer.accountNumber) ? \$vars.start.output.webhookPayload.customer.accountNumber : ''}'\`\"
    }
}

erp_detail = {
    'connectionId': 'd61e5d0e-04af-4f93-95cc-151d81fa08dc',
    'folderKey': 'c4359cde-55f0-4f0e-9322-c6cdce74ab4c',
    'method': 'POST',
    'endpoint': '/v2/{entityName}/qer',
    'pathParameters': {
        'entityName': 'BillingDisputeERP'
    },
    'queryParameters': {
        'queryExpression': \"=js:(() => { var inv = (\$vars.start.output.webhookPayload && \$vars.start.output.webhookPayload.invoice && \$vars.start.output.webhookPayload.invoice.invoiceNumber) ? \$vars.start.output.webhookPayload.invoice.invoiceNumber : ''; var norm = inv.trim().toUpperCase(); if (!norm.startsWith('MCS-')) norm = 'MCS-' + norm; return \`invoiceNumber = '\${norm}'\`; })()\"
    }
}

with open('/tmp/crm_detail.json', 'w') as f:
    json.dump(crm_detail, f)
with open('/tmp/erp_detail.json', 'w') as f:
    json.dump(erp_detail, f)

print('CRM:', json.dumps(crm_detail))
print()
print('ERP:', json.dumps(erp_detail))
"

